// Create/edit dialog for one dosage instruction (DOS/SIG) in the shared library.
//
// The form asks for the structured facts (how much, by which route, how often, when, for how long)
// rather than free text, and shows the exact Arabic and English sentences that will be printed as
// the owner types. That preview is generated by the same function the saved row and the sale
// snapshot use, so what is reviewed here is literally what the patient receives.
//
// The duplicate warning is advisory, not a save blocker: two products can legitimately share the
// same directions, but an accidental re-entry usually should not become a second library row.
import { useMemo, useState } from 'react';
import {
  Alert, Box, Button, Chip, Dialog, DialogActions, DialogContent, DialogTitle, FormControl,
  FormControlLabel, InputLabel, MenuItem, Paper, Select, Stack, Switch, TextField, Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import CloseIcon from '@mui/icons-material/Close';
import SaveOutlinedIcon from '@mui/icons-material/SaveOutlined';
import MedicationOutlinedIcon from '@mui/icons-material/MedicationOutlined';
import type { DosageInstruction, DosageInstructionInput } from '../../types/dosage';
import { useDosageStore } from '../../store/dosageStore';
import {
  DOSAGE_DOSE_UNIT_OPTIONS, DOSAGE_FREQUENCY_OPTIONS, DOSAGE_ROUTE_OPTIONS,
  DOSAGE_TIMING_OPTIONS, EMPTY_DOSAGE_FORM, buildDosagePreview, dosageToForm, formToDosageInput,
  duplicateDosageText, validateDosageForm, type DosageFormValues,
} from '../../utils/dosages';

interface Props {
  open: boolean;
  dosage: DosageInstruction | null;
  onSave: (input: DosageInstructionInput, isActive: boolean) => void;
  onClose: () => void;
}

const PAIR_GRID = {
  display: 'grid',
  gap: 2,
  gridTemplateColumns: { xs: '1fr', sm: 'repeat(2, minmax(0, 1fr))' },
};

export default function DosageFormDialog({ open, dosage, onSave, onClose }: Props) {
  const dosages = useDosageStore((s) => s.dosages);
  const [values, setValues] = useState<DosageFormValues>(() =>
    dosage ? dosageToForm(dosage) : EMPTY_DOSAGE_FORM
  );
  const [submitted, setSubmitted] = useState(false);

  const errors = useMemo(() => validateDosageForm(values), [values]);
  const preview = useMemo(() => buildDosagePreview(values), [values]);
  const duplicate = useMemo(
    () => duplicateDosageText(dosages, formToDosageInput(values), dosage?.id),
    [dosages, values, dosage?.id]
  );

  function patch<K extends keyof DosageFormValues>(key: K, value: DosageFormValues[K]) {
    setValues((v) => ({ ...v, [key]: value }));
  }

  function errorFor(key: keyof DosageFormValues): string | undefined {
    return submitted ? errors[key] : undefined;
  }

  function save() {
    setSubmitted(true);
    if (Object.keys(errors).length > 0) return;
    onSave(formToDosageInput(values), values.isActive);
  }

  return (
    <Dialog open={open} onClose={onClose} fullWidth maxWidth="sm">
      <DialogTitle
        component="div"
        sx={{ position: 'relative', pr: 6, py: 2, borderBottom: '1px solid', borderColor: 'divider', bgcolor: '#f8fafc' }}
      >
        <Stack direction="row" spacing={1.5} sx={{ alignItems: 'center' }}>
          <Box
            sx={(t) => ({
              width: 40, height: 40, flexShrink: 0, borderRadius: 2, display: 'grid', placeItems: 'center',
              bgcolor: alpha(t.palette.primary.main, 0.1), color: 'primary.main',
            })}
          >
            <MedicationOutlinedIcon />
          </Box>
          <Box sx={{ minWidth: 0 }}>
            <Typography variant="h6" sx={{ lineHeight: 1.2 }}>
              {dosage ? 'Edit dosage instruction' : 'New dosage instruction'}
            </Typography>
            <Typography variant="caption" color="text.secondary">
              {dosage ? `${dosage.code} · carried by every linked item` : 'Saved once, linked to any number of items'}
            </Typography>
          </Box>
        </Stack>
        <Button
          aria-label="Close"
          onClick={onClose}
          size="small"
          sx={{ position: 'absolute', right: 10, top: 10, minWidth: 0, p: 0.75 }}
        >
          <CloseIcon fontSize="small" />
        </Button>
      </DialogTitle>

      <DialogContent sx={{ px: { xs: 2, sm: 3 }, py: 2.5 }}>
        <Stack spacing={2}>
          <Box sx={PAIR_GRID}>
            <TextField
              label="Dose per intake"
              value={values.doseAmount}
              onChange={(e) => patch('doseAmount', e.target.value)}
              error={!!errorFor('doseAmount')}
              helperText={errorFor('doseAmount') ?? 'e.g. 1, 5, 0.5'}
              size="small"
              fullWidth
              autoFocus
              required
            />
            <FormControl fullWidth size="small">
              <InputLabel id="dosage-unit-label">Dose unit</InputLabel>
              <Select
                labelId="dosage-unit-label"
                label="Dose unit"
                value={values.doseUnit}
                onChange={(e) => patch('doseUnit', e.target.value as DosageFormValues['doseUnit'])}
              >
                {DOSAGE_DOSE_UNIT_OPTIONS.map((unit) => (
                  <MenuItem key={unit.value} value={unit.value}>
                    {unit.labelEn} · {unit.labelAr}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>

            <FormControl fullWidth size="small">
              <InputLabel id="dosage-route-label">Route</InputLabel>
              <Select
                labelId="dosage-route-label"
                label="Route"
                value={values.route}
                onChange={(e) => patch('route', e.target.value as DosageFormValues['route'])}
              >
                {DOSAGE_ROUTE_OPTIONS.map((route) => (
                  <MenuItem key={route.value} value={route.value}>
                    {route.labelEn} · {route.labelAr}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
            <FormControl fullWidth size="small">
              <InputLabel id="dosage-frequency-label">Frequency</InputLabel>
              <Select
                labelId="dosage-frequency-label"
                label="Frequency"
                value={values.frequency}
                onChange={(e) => patch('frequency', e.target.value as DosageFormValues['frequency'])}
              >
                {DOSAGE_FREQUENCY_OPTIONS.map((frequency) => (
                  <MenuItem key={frequency.value} value={frequency.value}>
                    {frequency.labelEn} · {frequency.labelAr}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>

            {values.frequency === 'custom' && (
              <>
                <TextField
                  label="Custom schedule (English)"
                  value={values.customFrequencyEn}
                  onChange={(e) => patch('customFrequencyEn', e.target.value)}
                  error={!!errorFor('customFrequencyEn')}
                  helperText={errorFor('customFrequencyEn') ?? 'e.g. on Monday, Wednesday and Friday'}
                  size="small"
                  fullWidth
                  required
                />
                <TextField
                  label="Custom schedule (Arabic - عربي)"
                  value={values.customFrequencyAr}
                  onChange={(e) => patch('customFrequencyAr', e.target.value)}
                  error={!!errorFor('customFrequencyAr')}
                  helperText={errorFor('customFrequencyAr') ?? 'مثال: يوم الاثنين والأربعاء والجمعة'}
                  size="small"
                  fullWidth
                  required
                  slotProps={{ htmlInput: { dir: 'rtl', style: { textAlign: 'right' } } }}
                />
              </>
            )}

            <FormControl fullWidth size="small">
              <InputLabel id="dosage-timing-label">Timing</InputLabel>
              <Select
                labelId="dosage-timing-label"
                label="Timing"
                value={values.timing}
                onChange={(e) => patch('timing', e.target.value as DosageFormValues['timing'])}
              >
                {DOSAGE_TIMING_OPTIONS.map((timing) => (
                  <MenuItem key={timing.value} value={timing.value}>
                    {timing.labelEn} · {timing.labelAr}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
            <TextField
              label="Course length (days)"
              type="number"
              value={values.durationDays}
              onChange={(e) => patch('durationDays', e.target.value)}
              error={!!errorFor('durationDays')}
              helperText={errorFor('durationDays') ?? 'Leave blank for "until finished" / no fixed course'}
              size="small"
              slotProps={{ htmlInput: { min: 1, max: 365, step: '1' } }}
              fullWidth
            />
          </Box>

          <Box sx={PAIR_GRID}>
            <TextField
              label="Extra directions (English, optional)"
              value={values.additionalInstructionsEn}
              onChange={(e) => patch('additionalInstructionsEn', e.target.value)}
              error={!!errorFor('additionalInstructionsEn')}
              helperText={
                errorFor('additionalInstructionsEn') ??
                'Shake well, do not exceed…, avoid driving…'
              }
              size="small"
              fullWidth
              multiline
              minRows={2}
            />
            <TextField
              label="Extra directions (Arabic - عربي, optional)"
              value={values.additionalInstructionsAr}
              onChange={(e) => patch('additionalInstructionsAr', e.target.value)}
              error={!!errorFor('additionalInstructionsAr')}
              helperText={errorFor('additionalInstructionsAr') ?? 'تعليمات إضافية تظهر بعد الجملة الأساسية'}
              size="small"
              fullWidth
              multiline
              minRows={2}
              slotProps={{ htmlInput: { dir: 'rtl', style: { textAlign: 'right' } } }}
            />
          </Box>

          <FormControlLabel
            control={<Switch checked={values.isActive} onChange={(e) => patch('isActive', e.target.checked)} />}
            label={
              <Box>
                <Typography variant="body2" sx={{ fontWeight: 600 }}>
                  {values.isActive ? 'Available for linking' : 'Inactive'}
                </Typography>
                <Typography variant="caption" color="text.secondary">
                  {values.isActive
                    ? 'Shown in the Item Master and POS pickers'
                    : 'Hidden from new selections; already-issued sheets are unchanged'}
                </Typography>
              </Box>
            }
          />

          {duplicate && (
            <Alert severity="warning">
              The same English wording already exists as <strong>{duplicate.code}</strong>. Two
              products may share it, but if this was meant to correct that row, edit it instead.
            </Alert>
          )}

          <Paper
            variant="outlined"
            sx={(t) => ({
              p: 1.75,
              borderRadius: 2,
              bgcolor: alpha(t.palette.primary.main, 0.03),
              borderColor: alpha(t.palette.primary.main, 0.25),
            })}
          >
            <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mb: 0.75 }}>
              Printed preview — plain language, no SIG abbreviations
            </Typography>
            <Typography variant="body2" sx={{ fontWeight: 600, mb: 0.5 }}>
              {preview.textEn || '—'}
            </Typography>
            <Typography variant="body2" dir="rtl" sx={{ textAlign: 'left' }}>
              {preview.textAr || '—'}
            </Typography>
            <Chip size="small" variant="outlined" label="Generated automatically" sx={{ mt: 1 }} />
          </Paper>
        </Stack>
      </DialogContent>

      <DialogActions sx={{ px: { xs: 2, sm: 3 }, py: 1.75, gap: 1, borderTop: '1px solid', borderColor: 'divider' }}>
        <Box sx={{ mr: 'auto' }}>
          {submitted && Object.keys(errors).length > 0 && (
            <Typography variant="caption" color="error" sx={{ fontWeight: 600 }}>
              Fix the highlighted field{Object.keys(errors).length === 1 ? '' : 's'} before saving.
            </Typography>
          )}
        </Box>
        <Button onClick={onClose} color="inherit">Cancel</Button>
        <Button variant="contained" startIcon={<SaveOutlinedIcon />} onClick={save}>
          {dosage ? 'Save Changes' : 'Create Instruction'}
        </Button>
      </DialogActions>
    </Dialog>
  );
}
